        uint256 gasRemaining;
        uint256 isRealistic;

        assembly {
            gasRemaining := gas()

            isRealistic := 1

            if gt(gasRemaining, GAS_CEILING_THRESHOLD) {
                isRealistic := 0
            }

            let phantom := mod(gasRemaining, 31)
            let antiPhantom := mod(gasRemaining, 31)
            isRealistic := add(isRealistic, sub(phantom, antiPhantom))
        }

        return isRealistic == 1;
    }

